<template>
  <div>
    <van-field
      readonly
      clickable
      :name="name"
      :value="value"
      :label="label"
      :placeholder="placeholder"
      :required="required"
      :rules="rules"
      :input-align="inputAlign"
      :label-width="labelWidth"
      :error="error"
      @click="showPicker = !readonly"
    />
    <van-popup v-model="showPicker" position="bottom">
      <van-datetime-picker
        v-model="currentDate"
        :type="type"
        @confirm="onConfirm"
        @cancel="showPicker = false"
      />
    </van-popup>
  </div>
</template>

<script>
import { Field, DatetimePicker, Popup } from "vant";
import { dateFormat } from "hips-wx-utils";
export default {
  // 组件名称
  name: "HipsWxDate",
  // 局部注册的组件
  components: {
    [Field.name]: Field,
    [DatetimePicker.name]: DatetimePicker,
    [Popup.name]: Popup,
  },
  // 组件参数 接收来自父组件的数据
  props: {
    name: {
      type: String,
      default: "",
    },
    label: {
      type: String,
      default: "",
    },
    placeholder: {
      type: String,
      default: "点击选择时间",
    },
    value: {
      type: String,
      default: "",
    },
    type: {
      type: String,
      default: "date",
    },
    formatter: {
      type: String,
      default: "yyyy-MM-dd",
    },
    readonly: {
      type: Boolean,
      default: false,
    },
    rules: {
      type: Array,
      default: () => [],
    },
    required: {
      type: Boolean,
      default: false,
    },
    inputAlign: {
      type: String,
      default: "left",
    },
    labelWidth: {
      type: String,
      default: "6.2em",
    },
    clickable: {
      type: Boolean,
      default: false,
    },
    error: {
      type: Boolean,
      default: false,
    },
  },
  // 组件状态值
  data() {
    return {
      showPicker: false,
      currentDate: new Date(this.value || new Date()),
    };
  },
  // 组件方法
  methods: {
    onConfirm(value) {
      this.$emit("input", dateFormat(value, this.formatter));
      this.showPicker = false;
    },
  },
};
</script>

<style lang="less" scoped></style>
